// Generated from the logo animation's frames (1280×660, 24fps). The bands are traced from
// the last frame and revealed along hand-drawn centre lines; the eye and the hand move too
// intricately for that, so each of their frames is traced (a vector flipbook), merging
// frames that don't visibly change. Arm timings are in seconds.

export type IntroLogoArm = {
    // Index into INTRO_LOGO_BANDS: the band this arm reveals.
    band: number;
    d: string;
    width: number;
    grow: { delay: number; duration: number };
    fill: { delay: number; duration: number };
};

// Shown from frame `from` through frame `to`; layers drawn black, white, then orange.
export type IntroLogoFrame = { from: number; to: number; black: string; white: string; orange: string };

